import{_ as e,c as a,o as r,ag as d}from"./chunks/framework.C7v41-tM.js";const b=JSON.parse('{"title":"静态博客：源码与发布分开维护","description":"","frontmatter":{},"headers":[],"relativePath":"blog/static-blog-publishing.md","filePath":"blog/static-blog-publishing.md"}'),o={name:"blog/static-blog-publishing.md"};function i(l,t,s,n,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="静态博客-源码与发布分开维护" tabindex="-1">静态博客：源码与发布分开维护 <a class="header-anchor" href="#静态博客-源码与发布分开维护" aria-label="Permalink to &quot;静态博客：源码与发布分开维护&quot;">​</a></h1><p>静态网站可以由私有源码构建，再把经过审核的 HTML、CSS 和 JavaScript 发布给读者。网站公开与源码公开是两个独立决定。</p><h2 id="一个具体例子" tabindex="-1">一个具体例子 <a class="header-anchor" href="#一个具体例子" aria-label="Permalink to &quot;一个具体例子&quot;">​</a></h2><p>本博客用 VitePress 组织 Markdown 页面。源码在开发仓库维护，构建后的站点文件放入账号站点的 <code>blog/</code> 目录，读者通过 <code>/blog/</code> 访问。个人主页在根目录，两者各自构建。</p><table tabindex="0"><thead><tr><th>内容</th><th>用途</th><th>是否发布</th></tr></thead><tbody><tr><td>审核过的文章和项目介绍</td><td>提供读者可阅读的知识</td><td>是</td></tr><tr><td>HTML、样式和浏览器脚本</td><td>展示页面与本地搜索</td><td>是</td></tr><tr><td>简历、个人原始资料、环境配置</td><td>私人维护和开发</td><td>否</td></tr><tr><td>仓库历史、依赖目录与缓存</td><td>开发与构建</td><td>否</td></tr></tbody></table><p>浏览器脚本本身会公开，不能把密钥写入前端，再以“源码仓库私有”为理由认为它安全。</p><h2 id="路径与链接" tabindex="-1">路径与链接 <a class="header-anchor" href="#路径与链接" aria-label="Permalink to &quot;路径与链接&quot;">​</a></h2><p>部署到子路径时，构建的 <code>base</code> 必须与目录一致。例如本博客采用 <code>/blog/</code>，资源和内部页面链接也需要匹配该前缀。不能只复制一个首页，而漏掉文章页、资源与搜索数据。</p><p>站内链接用于连续阅读；其他网站在新标签页打开，保留当前阅读位置。更换正式地址时更新公开入口，不依赖旧模板网站自动跳转。</p><h2 id="发布前检查" tabindex="-1">发布前检查 <a class="header-anchor" href="#发布前检查" aria-label="Permalink to &quot;发布前检查&quot;">​</a></h2><p>先确定允许公开的页面，再构建、检查产物和链接。排除敏感页面也要检查搜索数据，避免正文没显示但仍能搜索到私人材料。页面可访问只说明发布成功，不能代替功能验收或完整安全审计。</p><p>VitePress 的路径和排除选项见 <a href="https://vitepress.dev/reference/site-config" target="_blank" rel="noreferrer">官方站点配置</a>，链接行为见 <a href="https://vitepress.dev/guide/routing" target="_blank" rel="noreferrer">官方路由说明</a>。本例核对于 2026-10-13。</p>',12)])])}const _=e(o,[["render",i]]);export{b as __pageData,_ as default};
